using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System.Linq;
using System.IO;
using ConRoi.Investigation.V36;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            if (EditorApplication.isPlaying)
                throw new System.Exception("Edit only");
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            var scene = s.gameObject.scene;
            var all = scene.GetRootGameObjects().SelectMany(g => g.GetComponentsInChildren<Transform>(true)).ToArray();
            var old = all.SingleOrDefault(t => t.name == "R35_Roi_tai_quay");
            if (old)
                Object.DestroyImmediate(old.gameObject);
            var ha = s.GetComponentsInChildren<InvestigationActor>().Single(a => a.name == "Ha_Investigation");
            ha.transform.localRotation = Quaternion.identity;
            var khai = s.transform.Find("Workshop_GDD36/Khai_Investigation");
            khai.localRotation = Quaternion.Euler(0, 270, 0);
            foreach (var ani in s.GetComponentsInChildren<Animator>())
                ani.enabled = false;
            foreach (var ani in s.GetComponentsInChildren<Animation>())
                ani.enabled = false;
            string t = "Scene=" + scene.path + " old head count=" + scene.GetRootGameObjects().SelectMany(g => g.GetComponentsInChildren<Transform>(true)).Count(x => x.name == "ConRoi_Head_SameAsMinh") + "\n";
            foreach (var g in s.GetComponentsInChildren<ReturnGateMechanism>())
                t += "gate " + g.name + " line=" + (g.releaseLine != null) + " wedge=" + (g.wedgeVisual != null) + "\n";
            t += "clip camera=" + (s.clipCamera != null) + " coat at=" + s.transform.Find("Workshop_GDD36/Evidence_coat").position + "\n";
            File.WriteAllText("Test/KetQua/investigation_r102/final-edit-check.txt", t);
            EditorSceneManager.MarkSceneDirty(scene);
            EditorSceneManager.SaveScene(scene);
            r.Log(t);
        }
    }
}

